// Üretilen dosya: tool/ozgun/uret.py. Sanat · Fotoğraf sanatı ve fotoğraf tarihi (kolay).
const ozArt10Kolay = <(String, String, List<String>, String)>[
  ('Işığın küçük bir delikten karanlık bir odaya girip karşı duvarda dış dünyanın ters görüntüsünü oluşturması ilkesine dayanan, adı Latincede "karanlık oda" anlamına gelen düzenek hangisidir?', 'Camera obscura', ['Camera lucida', 'Sihirli fener', 'Stereoskop'], 'Camera obscura, fotoğraf makinesinin atasıdır; ışık küçük bir açıklıktan geçerek karşı yüzeyde ters bir görüntü oluşturur.'),
  ('11. yüzyılda yazdığı optik kitabında karanlık oda düzeneğini ve ışığın doğrusal yayılmasını deneylerle inceleyen Basra doğumlu bilgin kimdir?', 'İbnü\'l-Heysem', ['Ebû Reyhân el-Bîrûnî', 'İbn Sînâ', 'Harezmî'], 'İbnü\'l-Heysem (Alhazen), Kitâbü\'l-Menâzır adlı yapıtında karanlık oda deneylerini ve görme kuramını ayrıntılı biçimde ele almıştır.'),
  ('Bugün bilinen en eski kamera fotoğrafı sayılan, Saint-Loup-de-Varennes\'teki evinin üst kat penceresinden görünen avluyu ve çatıları kaydeden mucit kimdir?', 'Joseph Nicéphore Niépce', ['Louis Daguerre', 'Hippolyte Bayard', 'William Henry Fox Talbot'], 'Niépce\'nin 1820\'lerin ortasında Le Gras\'taki evinden çektiği bu görüntü, kamera ile elde edilip günümüze ulaşan en eski fotoğraf kabul edilir.'),
  ('Niépce kendi geliştirdiği ve "güneşle çizim" anlamına gelen fotoğraf yöntemine hangi adı vermiştir?', 'Heliografi', ['Fotojenik çizim', 'Siyanotip', 'Ambrotip'], 'Yunanca helios (güneş) ve graphein (yazmak, çizmek) sözcüklerinden türeyen heliografi, Niépce\'nin bitüm kaplı levhalarla çalışan yöntemidir.'),
  ('Niépce\'nin heliografilerinde ışığa duyarlı madde olarak kullandığı ve ışık gören yerlerde sertleşip çözünmez hâle gelen malzeme hangisidir?', 'Judea bitümü', ['Gümüş iyodür', 'Demir amonyum sitrat çözeltisi', 'Gümüş klorür'], 'Bitüm ışık aldıkça sertleşir; ışık görmeyen yumuşak kısımlar lavanta yağı ve beyaz petrol karışımıyla yıkanarak görüntü ortaya çıkarılırdı.'),
  ('Dagerreyotip yönteminde levhadaki görünmez görüntüyü görünür kılmak için hangi buhar kullanılırdı?', 'Cıva buharı', ['İyot buharı', 'Brom buharı', 'Amonyak buharı'], 'Levha önce iyot buharıyla duyarlı kılınır, kamerada pozlanır, ardından ısıtılmış cıvanın buharına tutularak görüntü ortaya çıkarılırdı.'),
  ('Bir müzede incelenen dagerreyotipin taşıyıcı yüzeyi aşağıdakilerden hangisidir?', 'Gümüş kaplı, cilalı bakır levha', ['Albüminle kaplanmış ince kâğıt', 'Siyaha boyanmış ince demir levha', 'Kolodyon sürülmüş cam levha'], 'Dagerreyotip, cilalı gümüş kaplama bir bakır levha üzerinde oluşan tek ve doğrudan pozitif görüntüdür.'),
  ('Dagerreyotip portrelerde saç ayrımının ya da düğmelerin taraflarının ters görünmesinin nedeni nedir?', 'Görüntünün levhada ayna görüntüsü olarak kalması', ['Fotoğrafçıların modelleri aynaya baktırması', 'Levhaların sergilenirken arkadan aydınlatılması', 'Kamera merceklerinin görüntüyü iki kez ters çevirmesi'], 'Dagerreyotipte ara negatif yoktur; levhada oluşan görüntü yanal olarak terstir. Bu yüzden bazı kameralarda düzeltici ayna ya da prizma kullanılırdı.'),
  ('Fotoğrafçıların sabitleyici banyoya bugün hâlâ "hipo" demesinin kökeni nedir?', 'Sodyum tiyosülfatın eski adının "sodyum hiposülfit" olması', ['Banyonun ilk kez Hipokrat\'ın tarifinden yapılması', 'Sabitleyicinin hipotermi yaratacak kadar soğuk kullanılması', 'Kimyasalın ilk üreticisinin adının Hippo olması'], 'Sabitleyici olarak kullanılan sodyum tiyosülfat 19. yüzyılda yanlış olarak sodyum hiposülfit diye adlandırılıyordu; kısaltma "hipo" olarak kalmıştır.'),
  ('Az pozlanmış bir kolodyon cam negatifin arkasına siyah kadife ya da koyu vernik konunca görüntünün pozitif gibi görünmesi ilkesine dayanan ucuz portre türü hangisidir?', 'Ambrotip', ['Tintip', 'Dagerreyotip', 'Platinotip'], 'Ambrotipte cam üzerindeki açık renkli gümüş, koyu fon önünde açık ton, saydam kalan bölgeler ise koyu ton olarak görünür; böylece negatif pozitif gibi algılanır.'),
  ('19. yüzyılın ikinci yarısında en yaygın kullanılan fotoğraf baskı kâğıdında gümüş tuzlarını kâğıt yüzeyinde tutan bağlayıcı neydi?', 'Yumurta akı', ['Hayvansal jelatin', 'Arap zamkı', 'Patates nişastası'], 'Albümin baskıda kâğıt tuzlu yumurta akıyla kaplanıp gümüş nitratla duyarlılaştırılırdı; bu sayede görüntü lifler arasına batmadan parlak bir yüzeyde kalırdı.'),
  ('1860\'larda insanların kraliyet ailesi, oyuncu ve siyasetçilerin küçük kartvizit portrelerini satın alıp albümlerde biriktirmesi biçimindeki modaya ne ad verilir?', 'Kartomani', ['Stereomani', 'Albümizm', 'Fotojeni'], 'Kartvizit portrelerin ucuzlayıp çoğalmasıyla ünlülerin fotoğrafları seri hâlinde satılmış, bu toplama tutkusu "kartomani" diye anılmıştır.'),
  ('Stereoskopik fotoğrafta derinlik yanılsaması nasıl oluşturulur?', 'Göz aralığı kadar ayrık iki noktadan çekilen iki görüntü ayrı gözlere gösterilerek', ['Aynı görüntünün kırmızı ve yeşil renkli iki kopyası kâğıda hafifçe kaydırılarak basılarak', 'Tek görüntü çok yakından büyük bir mercekle izlenerek', 'Görüntü dönen bir silindirin içinde art arda gösterilerek'], 'Beyin, gözlere ulaşan bu iki hafif farklı görüntüyü birleştirerek derinlik algısı oluşturur; stereoskop bu ayrımı sağlar.'),
  ('19. yüzyıl manzara fotoğraflarında gökyüzünün çoğunlukla bembeyaz ve bulutsuz görünmesinin nedeni nedir?', 'Emülsiyonların mavi ışığa aşırı duyarlı olması', ['Fotoğrafların hep sisli günlerde çekilmesi', 'Baskı kâğıtlarının gri tonları gösterememesi', 'Objektiflerin gökyüzünü kadraj dışında bırakması'], 'Erken emülsiyonlar yeşil ve kırmızıya hemen hemen duyarsız, maviye ise çok duyarlıydı; manzara doğru pozlandığında mavi gök aşırı pozlanıp beyaz çıkıyordu.'),
  ('İlk Kodak makinesini kullanan biri 100 pozluk filmi bitirdiğinde ne yapıyordu?', 'Makineyi fabrikaya gönderip baskıları ve yeniden yüklenmiş makineyi alıyordu', ['Filmi evdeki banyoda kendisi geliştiriyordu', 'Makineyi yakındaki eczanede yeni filmle değiştiriyordu', 'Filmi karanlık bir odada makineden çıkarıp postayla en yakın stüdyoya yolluyordu'], 'Kodak sistemi, kullanıcıyı teknik işlerden kurtarmak için makinenin Rochester\'daki fabrikaya gönderilmesine dayanıyordu.'),
  ('Kodak\'ın 1900\'de yalnızca 1 dolara satışa sunduğu ve özellikle çocuklara yönelik pazarlanan karton gövdeli makinenin adı nedir?', 'Brownie', ['Instamatic', 'Retina', 'Bantam'], 'Brownie, fiyatı ve kolaylığıyla fotoğrafı geniş kitlelerin, özellikle çocukların hobisi hâline getirmiştir.'),
  ('Fotoğraf ve sinema arşivlerinde eski nitrat filmlerin ayrı ve soğuk depolarda saklanmasının başlıca nedeni nedir?', 'Kolay tutuşması ve kendiliğinden bozunabilmesi', ['Işığa çok duyarlı kalıp kararması ve nemden dolayı mantar tutması', 'Nemden kolayca küf tutması', 'Manyetik alanlardan etkilenmesi'], 'Nitroselüloz taban yaşlandıkça bozunur ve çok kolay alev alır; bu yüzden arşivciler nitrat filmleri özel koşullarda korur ya da kopyalar.'),
  ('"Leica" marka adı nasıl oluşturulmuştur?', 'Leitz ve Camera sözcüklerinin ilk hecelerinden', ['Kurucunun kızının adından', 'Leipzig kentinin adından', 'Latince "hafif" anlamındaki sözcükten ve Latin dilinden gelen bir sözcük'], 'Ad, makineyi üreten Ernst Leitz firmasının adıyla "camera" sözcüğünün kısaltılıp birleştirilmesiyle oluşmuştur.'),
  ('Rolleiflex gibi çift objektifli refleks (TLR) makinelerde üst üste yerleştirilmiş iki objektifin görevi nedir?', 'Biri vizöre görüntü sağlarken öteki filmi pozlar', ['Biri renkli öteki siyah beyaz çeker', 'Biri yakın öteki uzak konular için kullanılır ve ayrı bir pozlama düzeneği olması', 'İkisi birlikte stereo görüntü oluşturur'], 'Üstteki objektif aynayla bel hizası buzlu cama görüntü verir, alttaki objektif ise çekimi yapar; bu yüzden çekim sırasında görüntü kararmaz.'),
  ('Orta format fotoğrafçılıkta en yaygın kullanılan, kâğıt arkalıklı rulo film türü hangisidir?', '120 film', ['135 film', '110 film', 'APS film'], '120 rulo film, 6 × 4,5, 6 × 6 ve 6 × 7 cm gibi kare boyutlarında kullanılan orta format filmdir; 135 ise 35 mm kartuşlu filmin kodudur.'),
  ('Edwin Land\'e anında fotoğraf fikrini verdiği anlatılan olay hangisidir?', 'Küçük kızının çekilen fotoğrafı neden hemen göremediklerini sorması', ['Bir savaş muhabirinin filmlerinin yolda bozulması', 'Bir laboratuvar kazasında filmin kendiliğinden gelişmesi ve denemenin sonucunu kimyasal olarak görmesi', 'Bir gazetenin baskıya çabuk fotoğraf istemesi'], 'Land\'in anlattığına göre 1943\'teki bir tatilde kızı fotoğrafı neden hemen göremeyeceklerini sormuş; bu soru kendiliğinden gelişen filmin araştırılmasını başlatmıştır.'),
  ('Kodachrome filmlerin sıradan fotoğraf laboratuvarlarında banyo edilemeyip özel tesislere gönderilmesinin nedeni nedir?', 'Renk bağlayıcıların banyo sırasında eklenmesi', ['Filmin ancak sıfırın altındaki sıcaklıklarda banyo edilebilmesi', 'Banyonun radyoaktif kimyasallar gerektirmesi', 'Görüntünün yalnız lazerle okunabilmesi'], 'Kodachrome\'un emülsiyonu aslında siyah beyazdır; renkler, karmaşık ve çok aşamalı banyoda her katmana ayrı ayrı katılır.'),
  ('Renkli tersinir (slayt) film ile renkli negatif film arasındaki temel fark nedir?', 'Slayt filmi banyodan sonra doğrudan pozitif görüntü verir', ['Slayt filmi yalnız siyah beyaz görüntü kaydedebilir', 'Negatif film banyo gerektirmeden doğrudan izlenebilir ve ek kimyasal gerektirmeden', 'Negatif film yalnız stüdyo flaşıyla kullanılabilir'], 'Tersinir banyo görüntüyü pozitife çevirdiğinden slaytlar projeksiyonla ya da ışıklı masada doğrudan izlenir; negatiften ise baskı almak gerekir.'),
  ('Renkli fotoğraf yaygınlaşmadan önce portre ve manzara fotoğraflarına renk katmak için en çok başvurulan yöntem hangisiydi?', 'Baskıların fırçayla elle boyanması', ['Objektife renkli cam takılması', 'Baskı kâğıdının renkli kumaşla kaplanması', 'Negatifin renkli ışıkla ikinci kez pozlanması'], '19. yüzyıl stüdyolarında suluboya, pastel ya da anilin boyalarla elle renklendirme yaygındı; Japonya\'daki Yokohama fotoğrafları bunun ünlü örnekleridir.'),
  ('Birden çok negatifin aynı kâğıda maskeler yardımıyla sırayla basılarak tek bir sahne oluşturulduğu 19. yüzyıl tekniğine ne ad verilir?', 'Kombinasyon baskı', ['Kontakt baskı', 'Fotogram', 'Solarizasyon'], 'Kombinasyon baskıda görüntü kesilip yapıştırılmaz; her negatif, öbür bölgeler örtülerek aynı kâğıda ayrı ayrı basılır ve kusursuz geçişli tek bir sahne elde edilir.'),
  ('19. yüzyılın sonunda fotoğrafın sanat sayılması için yumuşak odak, elle müdahaleli baskılar ve resimsel konular kullanan uluslararası akım hangisidir?', 'Piktoryalizm', ['Doğrudan fotoğraf', 'Yeni Nesnellik', 'Konstrüktivizm'], 'Piktoryalistler fotoğrafı mekanik kayıt olmaktan çıkarıp resim gibi yorumlanmış, eşsiz baskılara dönüştürmek istemişlerdir.'),
  ('Piktoryalistlerin sevdiği, pigmentli zamk katmanının fırçayla açılıp koyulaştırılabildiği ve her baskıyı tek kılan yöntem hangisidir?', 'Gum bikromat baskı', ['Albümin baskı', 'Jelatin gümüş baskı', 'Siyanotip baskı'], 'Gum bikromatta ışıkla sertleşen pigmentli zamk katmanı banyo sırasında fırçayla işlenebilir; bu da baskıya resimsel bir yüzey kazandırır.'),
  ('Stieglitz\'in "291" galerisi fotoğraf dışında Amerikan sanat ortamına hangi katkıyı yapmıştır?', 'Matisse ve Picasso gibi Avrupalı modernistleri ABD\'de ilk kez sergilemiştir', ['Amerikan halk sanatı koleksiyonlarını ilk kez müzeye kazandırmıştır ve ünlü müzik sanatçılarını Avrupa\'dan getirmiştir', 'Amerikan Yerlisi seramiklerinin ilk satış merkezi olmuştur', 'Rönesans ustalarının eserlerini düzenli olarak satmıştır'], 'Küçük galeri, fotoğrafın yanı sıra Rodin çizimlerini, Matisse\'i, Picasso\'yu ve Afrika heykelini Amerikan izleyicisiyle buluşturmuştur.'),
  ('1920\'lerde manolya, agav ve kala zambağı gibi bitkilerin yakın çekim, keskin fotoğraflarıyla tanınan f/64 grubu üyesi kadın fotoğrafçı kimdir?', 'Imogen Cunningham', ['Gertrude Käsebier', 'Margaret Bourke-White', 'Berenice Abbott'], 'Cunningham\'ın bitki çalışmaları, doğal biçimlerin modernist bir soyutlama duygusuyla görülmesinin klasik örnekleridir.'),
  ('Elle müdahaleyi reddedip keskin odak, geniş ton aralığı ve rötuşsuz baskıyı savunan 20. yüzyıl başı fotoğraf anlayışına ne ad verilir?', 'Doğrudan fotoğraf', ['Piktoryalizm', 'Fotomontaj', 'Gerçeküstücülük'], 'Doğrudan (straight) fotoğraf, fotoğrafı resme benzetmeye çalışmak yerine aygıtın kendine özgü netliğini ve ayrıntı gücünü kullanmayı amaçlar.'),
  ('Man Ray\'in 1921-22 dolaylarında anahtar, tarak ve cam gibi nesneleri doğrudan ışığa duyarlı kâğıda koyarak elde ettiği, kamerasız görüntülere verdiği ad nedir?', 'Rayograf', ['Vortograf', 'Fotodinamik', 'Kliş-verre'], 'Man Ray bu yöntemi kendi soyadıyla anılan "rayograf" sözcüğüyle adlandırmış, Dada ve gerçeküstücülük çevresinde yöntemi yaygınlaştırmıştır.'),
  ('Rus Konstrüktivisti Aleksandr Rodçenko\'nun 1920\'lerin sonundaki fotoğraflarında sık kullandığı çarpıcı çekim yöntemi hangisidir?', 'Çok dik yukarıdan ve aşağıdan eğik açılı çekimler', ['Düz göz hizasında simetrik çekim', 'Yumuşak odaklı stüdyo portresi', 'Elle renklendirilmiş kartpostal biçimi ve karanlık odada kâğıda çizim'], 'Rodçenko merdiven, balkon ve apartman gibi konuları keskin diyagonallerle ve dik açılarla çekerek geleneksel "burjuva" bakışa karşı yeni bir görsel dil önermiştir.'),
  ('John Heartfield\'ın 1930\'larda yayımladığı fotomontajlar en çok hangi amaçla kullanılmıştır?', 'Nazizme karşı siyasi karşı-propaganda yürütmek', ['Moda dergilerini süslemek', 'Reklam afişleri hazırlamak', 'Seyahat rehberlerini resimlemek ve mizah dergilerini süslemek'], 'Heartfield, "Arbeiter-Illustrierte-Zeitung" dergisinin kapaklarında Hitler\'i ve Nazi rejimini hicveden montajlar yayımlamıştır.'),
  ('Bir fotoğrafçı, bir zeytin ağacının dalını, bir mimari gövdeyi ve bir makinenin dişlisini aynı keskinlik ve tarafsızlıkla çekiyor. Bu tutum hangi akımın özelliğidir?', 'Yeni Nesnellik', ['Piktoryalizm', 'Dadaizm', 'Fütürizm'], 'Konuyu duygusal yorumdan uzak, eşit netlik ve dikkatle kaydetmek, 1920\'lerde Almanya\'da gelişen Yeni Nesnellik\'in belirgin özelliğidir.'),
  ('Brassaï\'nin 1933\'te yayımlanan "Geceleyin Paris" kitabının konusu nedir?', 'Gaz lambası, sis ve ışıkla aydınlanan gece sokakları, meyhaneler ve gece hayatı', ['Kentin gündüz pazarları, çiçekçileri ve meydanlarındaki kalabalıklar ve sabahın erken saatlerinde sakin sokaklar', 'Eyfel Kulesi\'nin yapım aşamaları ve işçileri', 'Seine nehri kıyısındaki balıkçılar ve eski kitap satıcıları'], 'Brassaï uzun pozlarla ve gece yürüyüşleriyle Paris\'in sokaklarını ve gece yaşamını sıra dışı bir atmosferle kaydetmiştir.'),
  ('Doisneau\'nun, Willy Ronis ve Izis\'in de aralarında bulunduğu Fransız fotoğraf akımına ne ad verilir?', 'Hümanist fotoğraf', ['Yeni Nesnellik', 'Piktoryalizm', 'Konstrüktivizm'], 'Savaş sonrasında sıradan insanların günlük yaşamına sıcak, şefkatli ve mizahi bir bakış getiren Fransız "humanist fotoğraf" akımının önde gelen isimleridir.'),
  ('Lewis Carroll\'un asıl adı nedir ve fotoğrafçılığa hangi alanla paralel olarak ilgi duymuştur?', 'Charles Dodgson; matematik öğretmenliğiyle', ['Lewis Dodgson; resim', 'Charles Darwin; tıp', 'Charles Dickens; yazarlık; Charles Dickens yazarlığa'], 'Oxford\'da matematik öğreten Dodgson, çocuk portrelerine özel ilgi göstermiştir. Alice Liddell\'in portreleri bunların en bilinenidir.'),
  ('Alfred Eisenstaedt\'in 1945\'te Times Meydanı\'nda çektiği "V-J Günü" fotoğrafında hangi olay gösterilir?', 'Bir denizcinin tanımadığı bir hemşireyi öpmesi', ['Askerlerin bayrak çekmesi', 'Bir çiftin evlenmesi', 'Bir gazetecinin kalabalığa seslenmesi ve arkasından yürümesi'], 'Japonya\'nın teslim olduğunun duyurulduğu gün kalabalığın coşkusunu yakalayan fotoğraf LIFE\'ta yayımlanmıştır.'),
  ('Stryker, kabul etmediği FSA negatiflerini nasıl yok ederdi?', 'Negatiflere delgeçle delik açarak', ['Yakarak', 'Banyoda silerek ve hiç yok etmeden saklayarak', 'Kırarak'], 'Stryker, istemediği kareleri "öldürmek" için negatiflere delik açar, bu uygulama bugün arşiv kaybı olarak eleştirilir.'),
  ('Gerda Taro\'nun fotoğraf tarihindeki yeri aşağıdakilerden hangisiyle açıklanır?', 'Savaş cephesinde ölen ilk kadın foto muhabirlerinden biri olması', ['İlk renkli savaş fotoğrafını çekmesi', 'Magnum\'un ilk başkanı olması', 'Mikrofotoğraf tekniğini bulması'], 'Capa\'nın yakın çalışma arkadaşı olan Taro, 1937\'de Brunete cephesinde bir tankın çarpmasıyla ölmüş, savaşta ölen ilk kadın foto muhabirlerinden sayılmıştır.'),
  ('World Press Photo vakfı 1955\'te hangi ülkede kurulmuştur?', 'Hollanda', ['Fransa', 'Birleşik Krallık', 'Amerika Birleşik Devletleri'], 'Amsterdam merkezli kuruluş, her yıl fotoğraf muhabirliği yarışması düzenleyerek yılın fotoğrafını belirler.'),
  ('Diane Arbus hangi fotoğrafçıdan ders almıştır?', 'Lisette Model', ['Edward Weston', 'Imogen Cunningham', 'Berenice Abbott'], 'Arbus, sokak insanlarına bakışı sert ve açık olan Viyana doğumlu hocasından aldığı derslerle kendi yolunu bulmuştur.'),
  ('Eggleston\'ın renkli fotoğraflarında kullandığı, doygun ve parlak renkler veren baskı yöntemi hangisidir?', 'Dye-transfer', ['Platin baskı', 'Albümin baskı', 'Siyanotip'], 'Dye-transfer, üç renk ayrımı negatifinden jelatin matrislerle boya aktararak canlı ve kalıcı renkler elde etmeye yarar.'),
  ('Bir sokak fotoğrafçısı, kalabalık bir yaya geçidinde birbirinden bağımsız beş kişinin aynı anda ilginç hareket yaptığı bir an yakalıyor. Bu tür karelerin başarısını en çok hangi yetenek belirler?', 'Olayı önceden sezerek doğru anda deklanşöre basmak', ['Pahalı flaş kullanmak', 'Sahneyi önceden düzenlemek', 'Kareyi sonradan boyamak'], 'Sokak fotoğrafında kadrajdaki öğelerin tesadüfi buluşmasını sezip tam anında çekmek belirleyici beceridir.'),
  ('Philippe Halsman\'ın ünlü portre seanslarında konuklarına yaptırdığı uygulama nedir?', 'Zıplatıp havada çekmek', ['Karanlıkta çekmek', 'Ayna karşısında çekmek', 'Dans ettirmek'], 'Halsman "zıplama" çekimleriyle ünlüleri havada yakalayarak maskelerinin düşmesini sağladığını söylemiştir.'),
  ('Salgado fotoğrafçılığa geçmeden önce hangi alanda eğitim almıştır?', 'Ekonomi', ['Tıp', 'Mimarlık', 'Hukuk'], 'Brezilyalı Salgado, ekonomist olarak Uluslararası Kahve Örgütü\'nde çalıştıktan sonra fotoğrafa yönelmiştir.'),
  ('Astronomide fotoğraf plakalarının gözle bakmaya göre başlıca üstünlüğü nedir?', 'Zayıf ışığın uzun pozlamayla birikip gözün göremediği cisimleri kaydetmesi', ['Gözden daha geniş renk görmesi', 'Işığın hızını ölçebilmesi', 'Teleskopsuz çalışabilmesi'], 'Fotoğraf plakası zayıf ışığı pozlama süresince toplar, böylece soluk yıldızlar ve bulutsular plakaya geçer, ayrıca kalıcı bir kayıt bırakır.'),
  ('Andreas Gursky, Thomas Struth ve Thomas Ruff\'ın ortak noktası aşağıdakilerden hangisidir?', 'Düsseldorf Sanat Akademisi\'nde Becherlerin öğrencisi olmaları', ['Aynı galeride çalışarak LIFE dergisine fotoğraf satmaları ve gazeteler için çekim yapmaları', 'Bauhaus okulunun son öğrencileri olmaları', 'Magnum ajansının kurucuları arasında bulunmaları'], 'Üçü de Bernd Becher\'in sınıfında yetişmiş, büyük format, soğuk ve nesnel bir bakışı sürdürmüştür.'),
  ('Thomas Struth\'un müze fotoğraflarının konusu nedir?', 'Müzelerde yapıtlara bakan ziyaretçiler', ['Müze binalarının dış cepheleri ve hiç kimse olmadan', 'Müze depolarındaki raflar', 'Müze çalışanlarının portreleri'], 'Struth, Louvre ve Prado gibi müzelerde izleyicilerin yapıtlarla ilişkisini büyük formatlı kareler hâlinde incelemiştir.'),
  ('Osmanlı\'da fotoğrafın 19. yüzyılın sonlarında saray çevresinde desteklenmesinin başlıca nedeni nedir?', 'Devletin imajını yönetmek ve imparatorluğu belgelemek', ['Resim sanatını yasaklamak', 'Askeri sansürü kolaylaştırmak', 'Bir basın kurumu kurmak'], 'Padişah yönetimi, fotoğrafı hem bilgi toplama hem de uluslararası algıyı biçimlendirme aracı olarak kullanmıştır.'),
  ('FSA fotoğrafçısı John Vachon\'un diğer fotoğrafçılardan farkı nedir?', 'Kuruma bir kâtip olarak girip sonra fotoğrafçı olması', ['En yaşlı üye olması', 'Renkli film kullanması', 'Avrupa\'dan gelmesi'], 'Vachon işe arşiv yardımcılığı ile başlamış, sonra kendini yetiştirip kırsal Amerika\'yı fotoğraflamıştır.'),
  ('Portrede ışığın yüzün bir yanındaki gölge tarafında, gözün altında ve yanakta küçük, ters bir üçgen aydınlık bırakan düzene ne ad verilir?', 'Rembrandt ışığı', ['Kelebek ışığı', 'Yarım ışık', 'Halka ışığı'], 'Anahtar ışığı yüzü 45 derecelik açıyla ve yukarıdan vurunca, gölgedeki yanakta Rembrandt\'ın tablolarındaki gibi ışık üçgeni oluşur.'),
  ('Işık kaynağı modelin tam yan tarafında olduğunda yüzün yarısı aydınlık, yarısı karanlık kalıyorsa kullanılan düzen hangisidir?', 'Bölünmüş (split) ışık', ['Kelebek ışığı: burnun altında simetrik küçük gölge bırakan düzen', 'Halka ışığı', 'Rembrandt ışığı'], 'Yüzü ikiye bölen sert bir çizgi dramatik, gizemli ve sert bir ruh hâli yaratır.'),
  ('Arka fonda neredeyse hiç gölge olmayan, ağırlıkla açık tonlu ve ışıklı bir portre çekimi için hangi terim kullanılır?', 'High-key', ['Low-key', 'Siluet', 'Rim ışığı'], 'Yüksek anahtar çekimlerde aydınlık tonlar baskındır; gölgeler yumuşaktır ve görüntü neşeli, hafif bir hava taşır.'),
  ('Siyah fonda yüzün yalnızca küçük bir bölümünü aydınlatan çekim hangi tür ışıklandırmayı örnekler?', 'Low-key', ['High-key', 'Düz ışık', 'Dolgu ışığı'], 'Düşük anahtar çekimde koyu tonlar baskındır; yüksek kontrast ve gölgeler dramatik bir ruh hâli kurar.'),
  ('Konunun arkasından ve yandan verilen, saç ve omuz çevresinde ince parlak bir çizgi oluşturan ışığa ne ad verilir?', 'Rim (kenar) ışığı', ['Anahtar ışık: sahnedeki en güçlü ve ana aydınlatma kaynağı', 'Dolgu ışığı', 'Ortam ışığı'], 'Rim ışığı, konuyu arka plandan ayırarak derinlik ve parlak bir kontur ekler.'),
  ('Bir ışık kaynağı konuya 2 m uzaklıktan 4 m\'ye çekilirse konunun aldığı ışık kaç durak azalır?', '2 durak: ışık dörtte bire iner', ['1 durak: ışık yarıya iner', '3 durak: ışık sekizde bire iner', '4 durak: ışık on altıda bire iner'], 'Işık şiddeti uzaklığın karesiyle ters orantılı olduğu için uzaklık iki katına çıkınca ışık dörtte bire iner, bu da iki duraktır.'),
  ('Bir stüdyoda ana ışık ile dolgu ışığı arasındaki oran 4:1 ise iki ışık arasındaki fark kaç duraktır?', '2 durak: log2(4) = 2', ['4 durak: log2(16) = 4', '1 durak: log2(2) = 1', '3 durak: log2(8) = 3 değerine denk gelir'], 'Oran 4:1 ise log2 4 = 2 olduğundan fark iki duraktır; oran büyüdükçe gölgeler koyulaşır.'),
  ('Stüdyoda çıplak bir flaş yerine büyük bir yumuşak kutu (softbox) kullanmak yüz portrelerinde nasıl bir fark yaratır?', 'Geçişleri yumuşatır, gölge kenarlarını belirsizleştirir', ['Gölgeleri daha sert ve koyu yapar, yüzdeki kusurları vurgular', 'Yüzü tamamen düz ve gölgesiz gösterir', 'Yalnızca renk sıcaklığını değiştirir'], 'Kaynak göreceli olarak geniş olunca ışık konuyu çok yönden sarar ve gölge kenarları yumuşar.'),
  ('Bir fotoğrafçı stüdyo flaşının önüne turuncu jel takarak ışığı neye uyarlamış olur?', 'Gün batımı ya da akkor ampulün sıcak rengine', ['Mavi saat gökyüzünün soğuk ve mavi tonuna uygun bir renge', 'Floresan lambaların yeşilimsi tonuna', 'Aydınlatmanın daha sert olmasına'], 'Turuncu jel ışığın renk sıcaklığını düşürerek sıcak bir ortam yaratır ya da ortamdaki tungsten ışıkla uyum sağlar.'),
  ('Flaşla fotoğraf çeken biri, perde deklanşörlü makinesinin en kısa "senkron hızı"nı aşarsa görüntüde ne ile karşılaşır?', 'Karenin bir bölümünün siyah bantla kapanmasıyla', ['Fotoğrafın tamamen beyaza dönmesiyle ve ayrıntı kaybıyla', 'Kırmızı göz etkisiyle', 'Renklerin ters dönmesiyle'], 'Flaş patladığında deklanşör perdeleri tamamen açık olmadığı için kadrajın bir kısmı perde tarafından kapatılır.'),
  ('Arka perdeye senkronizasyon (rear curtain sync) ile uzun pozlamada hareketli bir arabanın görüntüsü nasıl çıkar?', 'Işık izleri arkada kalır ve araç net biçimde ilerisinde görünür', ['Işık izleri aracın önünde görünür ve araç arkada bulanık, soluk biçimde kalır', 'Araç tamamen bulanık kalır', 'Araç tamamen görünmez olur'], 'Flaş pozlama sonunda patladığı için hareket izi önce gelir ve net görüntü o izin ucunda yer alır.'),
  ('Flaşın kılavuz sayısı (GN) 32 (metre, ISO 100) ise f/4 diyaframda ne kadar uzaktaki konuyu doğru aydınlatır?', '8 metre', ['4 metre', '16 metre', '128 metre'], 'Mesafe = GN / f sayısı = 32 / 4 = 8 metredir.'),
  ('TTL (through-the-lens) flaş ölçümü nasıl çalışır?', 'Makine, flaş patlamasının ışığını objektiften ölçüp süreyi otomatik keser', ['Flaş ışığını kameradan bağımsız olarak her çekimde sabit güçte ateşler ve süreyi sabit tutar', 'Flaşı ışık şiddetine göre yükseltir', 'Flaşın rengini sensör rengine göre uyarlar'], 'Çekim sırasında flaş ışığı sahneye vurup objektiften geri gelirken ölçülür; yeterli ışık gelince flaş kesilir.'),
  ('Flaşta yüksek hızlı senkronizasyon (HSS) ne işe yarar?', 'Normal senkron hızının üstündeki enstantanelerde de flaş kullanmaya', ['Flaşın şarj süresini kısaltıp seri çekimde daha hızlı yeniden ateşlemeye', 'Flaşı renkli göstermeye', 'Flaşı otomatik odaklamaya'], 'HSS, flaşı kısa seri atımlarla ateşleyerek hızlı enstantanelerde de dolgu flaşı verir; böylece gün ışığında açık diyaframla çalışılabilir.'),
  ('Halka flaşın objektifin çevresine yerleştirilmesi portrede nasıl bir sonuç verir?', 'Gölgeleri azaltıp gözlerde halka biçimli parıltı oluşturur', ['Gölgeleri keskinleştirir ve yüzdeki dokuyu abartarak öne çıkarır', 'Yalnızca yanak kemiklerini vurgular', 'Gözün tamamen karanlık çıkmasını sağlar'], 'Işık eksenden geldiği için gölgeler neredeyse kaybolur, gözbebeğinde halka şeklinde yansıma kalır.'),
  ('Karanlık bir odada çekim yapan fotoğrafçı flaşını dışa çevirip duvara yansıtırsa nasıl bir etki beklenir?', 'Daha geniş ve yumuşak bir ışık, daha az sert gölge', ['Daha sert ve dar gölgeler oluşturur, ışığın yönü belirginleşir', 'Işığın tamamen kaybolması', 'Fotoğrafın renkli olması'], 'Işık yüzeyde yayıldığı için etkin ışık kaynağı büyür; bu da yumuşak, yönsüz bir aydınlatma sağlar.'),
  ('Çok kısa bir flaş patlaması, ışıkla boyama yöntemine kıyasla neden hareketi dondurma konusunda daha başarılıdır?', 'Işık yalnızca saniyenin binde birinden kısa sürede verilir', ['Flaşın rengi daha parlaktır ve sensör bu yüzden daha çok ışık toplar', 'Flaşın alanı daha geniştir', 'Flaş ışığı yalnız mavidir'], 'Flaş süresi çok kısa olduğundan, konu o süre içinde neredeyse hiç yer değiştirmez ve donmuş görünür.'),
  ('Güneşin ufka yakın olduğu ilk ve son saatlerinde çekimin tercih edilmesinin nedeni nedir?', 'Işığın sıcak, yumuşak ve yanal olması', ['Işığın tamamen mavi ve soğuk olması, gölgelerin kaybolması', 'Güneşin çok sert olması', 'Gölgenin hiç oluşmaması'], 'Güneş ışınları atmosferde uzun yol katettiğinden ışık sıcaklaşır ve yan açıyla gelerek dokuları öne çıkarır.'),
  ('Polarizan filtre suyun ya da camın yüzeyindeki parlamayı neden azaltır?', 'Belirli doğrultuda polarize olmuş yansıyan ışığı keser', ['Işığın tüm dalga boylarını emer ve görüntüyü gri tona çevirir', 'Yüzeyin rengini değiştirir', 'Işığı belli bir yöne yoğunlaştırır'], 'Yüzeylerden yansıyan ışık kısmen polarizedir; filtre döndürülünce bu bileşen engellenir, parlama azalır ve renkler doygunlaşır.'),
  ('Polarizan filtrenin gökyüzünü en çok koyulaştırdığı konum, güneşe göre hangisidir?', 'Güneşe yaklaşık 90 derece açıyla bakıldığında', ['Doğrudan güneşe bakıldığında ve güneş yüzün arkasında kaldığında', 'Güneşe sırtını dönünce', 'Güneş tam tepedeyken'], 'Gökyüzü ışığındaki polarizasyon güneşe dik doğrultuda en güçlüdür; bu yüzden etki o doğrultuda en belirgindir.'),
  ('Bir ışık ölçerin, konunun üzerine düşen ışığı ölçen yarım küre başlıklı "gelen ışık" (incident) okumasının üstünlüğü nedir?', 'Konunun yansıtma oranından etkilenmemesi', ['Yalnızca uzaktaki parlak noktaları okuması', 'Karanlık sahneleri daha parlak göstermesi', 'Gün ışığında daha yüksek ISO verebilmesi'], 'Gelen ışık ölçümü, sahnedeki cismin beyaz mı koyu mu olduğundan bağımsızdır; bu yüzden karlı ya da koyu sahnelerde yanılmaz.'),
  ('Fotoğrafçıların kullandığı %18\'lik gri kartın görevi nedir?', 'Pozlama ve beyaz dengesi için orta gri referans vermek', ['Fotoğrafı elle koyulaştırıp gri tonlu baskı elde etmek için sensöre yerleştirilir', 'Flaş ışığını yansıtıp sahneyi renklendirmek', 'Dijital sensörü toz ve çizilmeden korumak'], 'Gri kart orta tonu temsil eder; üzerine yapılan ölçüm ya da özel beyaz dengesi, ışığın rengini ve miktarını doğru belirler.'),
  ('Aynı sahnenin bir durak az, normal ve bir durak fazla pozlanmış üç karesini ardışık çeken fotoğrafçı hangi yöntemi uygular?', 'Pozlama çatallama', ['Odak yığınlama (focus stacking) yöntemini', 'Panoramik birleştirme (stitching) yöntemini', 'Çoklu pozlama (multiple exposure) tekniğini'], 'Bu kareler HDR birleştirmede ya da doğru pozlamadan emin olunamayan durumlarda en iyi karenin seçilmesinde kullanılır.'),
  ('Dijital çekimde histogramı sağa yaklaştırıp parlak alanları patlatmadan mümkün olduğu kadar çok ışık toplamaya yarayan stratejiye ne ad verilir?', 'Sağa pozlama (ETTR)', ['Sola pozlama (ETTL) yöntemi', 'Çift pozlama (double exposure)', 'Çapraz pozlama (cross processing)'], 'Sensör parlak ışığı daha çok tonla kaydettiğinden sağa pozlanmış RAW dosyası, gölge gürültüsünü azaltarak daha temiz görüntü verir.'),
  ('Bir film fotoğrafçısı, uzun pozlamada ışık ölçerin hesapladığı süreyi aynen uygulayıp filmin beklenenden koyu çıktığını görüyor. Bu olaya ne ad verilir?', 'Karşılıksızlık (reciprocity) hatası', ['Parazit (gürültü) birikmesi sorunu ve ısınma etkisi', 'Enstantane gecikmesi', 'Odak kayması (focus shift) hatası'], 'Çok uzun pozlarda film, ışığa karşı duyarlılığını yitirir; bu yüzden hesaplanan süreden fazlası gerekir.'),
  ('1/250 saniyede doğru pozlanan bir sahneye on durak azaltan (ND1000) filtre takılırsa dengeli enstantane yaklaşık kaç saniye olur?', '4 saniye', ['1/4 saniye, çünkü süre kısalır', '40 saniye, çünkü yüz katı gerekir', '1 saniye, çünkü beş durak yeter'], 'Işık 1000 kat azaldığından süre yaklaşık 1000 kat uzar; 1000 / 250 = 4 saniye olur.'),
  ('Diyafram f/8, enstantane 1/125 ve ISO 100 olan bir ayarın yaklaşık pozlama değeri (EV) kaçtır?', '13 (log2 8000 ≈ 13)', ['8 (diyafram sayısına eşit)', '10 (log2 1000 ≈ 10)', '16 (f/16 ile aynı değer)'], 'EV = log2(N² / t) = log2(64 × 125) yaklaşık 13\'tür; bu değer güneşli bir gün için tipiktir.'),
  ('Az pozlanmış bir dijital fotoğrafın gölgeleri bilgisayarda yüksek oranda parlatılırsa ne tür bir görüntü sorunu belirgin olur?', 'Renk gürültüsü ve kalite kaybı', ['Kenarlarda parlak halo ve keskinlik artışı', 'Perspektif bozulması ve eğrilik', 'Kromatik sapma ve mor saçaklanma'], 'Gölge bölgelerde sensörün yakaladığı sinyal zayıftır; yükseltince gürültü de çarpılarak ortaya çıkar.'),
  ('Bir kentin gece manzarasını ışıklı pencereler ve sokak lambalarıyla net çekmek isteyen kişi için en uygun ayar hangisidir?', 'Tripot, ISO 100, f/8 ve birkaç saniyelik pozlama', ['Elde tutma, ISO 6400, f/1.4 ve 1/1000 saniye', 'Flaşlı çekim, ISO 3200, 1/60 saniye ve elde tutma', 'Elde tutma, ISO 800, f/2.8 ve 1/500 saniye'], 'Sabit makine düşük ISO ve orta diyaframla uzun süre pozlandığında ışıklar ayrıntılı, gürültü az ve görüntü keskin olur.'),
  ('Renkli negatif filmin aşırı pozlamaya, slayt filmine göre daha toleranslı olması neden avantajdır?', 'Çekim hatalarında bile ayrıntı kalır, baskıda düzeltilir', ['Slayt filminden her zaman çok daha ucuz olmasını sağlar', 'Filmi banyodan geçirme zorunluluğunu tamamen ortadan kaldırır', 'Her koşulda daha düşük ISO değeri sunmasını sağlar, bu da tane azaltır'], 'Negatifin geniş pozlama toleransı, hafif fazla ya da az pozlamanın baskıda düzeltilmesine olanak verir.'),
  ('Kadrajı yatay ve dikey birer çizgiyle üçe bölüp önemli öğeleri bu çizgilerin kesişimlerine yerleştirmeyi öneren kompozisyon ilkesine ne ad verilir?', 'Üçler kuralı', ['Altın üçgen', 'Merkez kuralı', 'Çerçeve kuralı'], 'Konunun ortaya konması durağan bir görünüm verir; kesişim noktalarına yerleştirmek dinamik bir denge sağlar.'),
  ('Bir yol, çit ya da nehir kıyısı gibi çizgilerin bakışı kadrajın içinde belirli bir noktaya taşıması hangi kompozisyon aracıdır?', 'Yönlendirici çizgiler', ['Negatif alan', 'Çerçeve içinde çerçeve', 'Doku tekrarı'], 'Yönlendirici çizgiler izleyicinin gözünü ön plandan konuya ve derine doğru yürütür.'),
  ('Telefoto objektifle uzaktan çekilen bir yolun üzerindeki arabaların birbirine çok yakınmış gibi görünmesinin nedeni nedir?', 'Telefoto, perspektifi sıkıştırarak uzaklık farklarını azaltır', ['Telefoto araçların gerçekte yakın olmasını sağlar ve arabaların hızını artırmasını', 'Telefoto görüntüyü yatay çevirir', 'Telefoto arabanın hızını yavaşlatır'], 'Uzun odak uzaklığı dar görüş açısıyla uzak plânları büyüterek derinlik farkını azaltır; bu da yakınlaşma izlenimi yaratır.'),
  ('Portre çekerken kişinin bakışı yönünde kadrajda boşluk bırakma ilkesine ne ad verilir?', 'Bakış boşluğu (lead room)', ['Baş boşluğu', 'Negatif zemin (modelin arkasında fazla boşluk)', 'Çerçeve payı'], 'Modelin baktığı yönde yer bırakmak görüntünün dengeli ve konunun nefes alıyor görünmesini sağlar.'),
  ('Bir manzara fotoğrafında gökyüzü ilginç değilse ufuk çizgisi nereye yerleştirilerek zemin vurgulanır?', 'Kadrajın üstteki üçte birine', ['Tam ortaya', 'Kadrajın en altına', 'Kadrajın dışına'], 'Ufuk üst çizgiye yaklaşınca fotoğrafın büyük kısmı zemine ayrılır ve gökyüzünün sıkıcılığı ikinci plana düşer.'),
  ('Bir fotoğrafçı kumsalda geniş açıyla çekerken önüne yakın bir kaya yerleştiriyor. Bu ön plan öğesi görüntüde ne işe yarar?', 'Derinlik ve ölçek duygusu katar', ['Görüntüyü soluklaştırır ve ayrıntıların kaybolması', 'Perspektifi kaldırır', 'Netlik alanını daraltır'], 'Yakın nesne, geniş açıda öne çıkarak iz sürülecek bir giriş noktası sağlar ve plânlar arasındaki derinliği artırır.'),
  ('Aynı biçimlerin ya da renklerin kadrajı dolduracak şekilde tekrarlandığı fotoğraflarda hangi görsel ilke baskındır?', 'Desen ve ritim', ['Siluet', 'Zıt renk', 'Negatif alan'], 'Tekrar eden öğeler ritim yaratır; desen kırıldığında ise dikkat kırılan öğeye çevrilir.'),
  ('Fotoğrafçıların bazen kadrajı kasıtlı olarak eğip yatay çizgileri çapraz konuma getirmesi hangi etkiyi sağlar?', 'Hareket ve gerilim duygusu', ['Görüntünün sakinleşmesi ve netliğin artması', 'Perspektifin tamamen kaybolması', 'Renklerin doygunlaşması'], 'Eğik çizgiler dinamik ve huzursuz bir his verir; Rodçenko ve Winogrand bu aracı sık kullanmıştır.'),
  ('Odak modunda AF-S (tek odak) ile AF-C (sürekli odak) arasındaki temel fark nedir?', 'AF-C, deklanşöre yarım basılı tutulurken hareket eden konuyu izlemeyi sürdürür', ['AF-S, hareketli konuyu sürekli takip ederken AF-C bir kez odaklayıp kilitler ve AF-C hiç odaklamaz', 'İkisi de aynıdır, yalnızca adları farklıdır', 'AF-S yalnızca karanlıkta çalışır, AF-C ise gün ışığında'], 'AF-S bir kez odaklayıp kilitler; AF-C ise konu hareket ettikçe odağı sürekli güncelleyerek spor ve yaban hayatı için uygundur.'),
  ('Arka düğme odaklama (back-button focus) yönteminin sağladığı başlıca kolaylık nedir?', 'Odaklamayı deklanşörden ayırıp bağımsız kontrol etmek', ['Pozlamayı otomatik hâle getirmek ve çekim sırasında otomatik kadraj', 'Diyaframı daha çabuk açmak', 'Flaşı hızlı şarj etmek'], 'Odak, arka düğmeye basılarak kilitlenir; deklanşör yalnızca çekim yapar, böylece odak ve kompozisyon bağımsız çalışır.'),
  ('Faz algılamalı otomatik odaklamanın kontrast algılamalıya göre başlıca üstünlüğü nedir?', 'Odağın hangi yönde kaydırılacağını tek ölçümle bilerek hızlı odaklanması', ['Mikrofon gibi sesle çalışması', 'Her zaman daha az enerji harcaması', 'Yalnızca videoda kullanılabilmesi'], 'Faz algılama, ışığın iki yoldan gelen görüntüsünü karşılaştırır ve odak farkının yönünü ve miktarını belirler; kontrast algılama ise deneyerek bulur.'),
  ('Odak tepe vurgusu (focus peaking) elle odaklamada nasıl yardımcı olur?', 'Net bölgelerin kenarlarını renkli çizgilerle işaretler', ['Pozlamayı otomatik düzeltir', 'Flaşı kapatır', 'Görüntüyü stabilize eder'], 'Kenar kontrastı yüksek olan alanlar ekranda renkli olarak parlar, fotoğrafçı bu sayede netlik düzlemini görür.'),
  ('Objektiflerin çoğunun en keskin olduğu diyafram aralığı nasıl bir bölgedir?', 'En geniş açıklıktan iki üç durak kısılmış orta diyaframlar', ['En geniş açıklık', 'En dar diyafram', 'Her diyaframda aynı keskinliktedir'], 'Tam açıklıkta aberasyonlar, çok dar diyaframda kırınım keskinliği azaltır; en iyi netlik genellikle ortada elde edilir.'),
  ('Düşük enstantanelerde elde çekimde görüntü stabilizasyonu (IS/VR) teknik olarak ne sağlar?', 'Titremeyi dengeleyerek birkaç durak daha yavaş enstantaneyle çekime izin verir', ['Konunun hareketini dondurur', 'Diyaframı otomatik açar', 'Renk sıcaklığını ayarlar'], 'Stabilizasyon, makine sarsıntısını telafi eder; ancak konunun kendi hareketinden kaynaklanan bulanıklığı gidermez.'),
  ('Aynalı makinede deklanşöre basıldığında aynanın çarpması bazen hafif bulanıklığa yol açar. Bu sorunu azaltmak için hangi özellik kullanılır?', 'Ayna kilitleme', ['Çoklu pozlama ve tripodsuz çekimde hız artırmak', 'Flaş senkronu', 'Histogram'], 'Ayna önceden kaldırılıp titreşim sönünce çekim yapılır; bu, uzun odaklarda ve makro çekimde işe yarar.'),
  ('Bir objektifin çevresinde köşelerin daha koyu çıkmasına ne ad verilir?', 'Vinyetleme', ['Parıldama', 'Distorsiyon', 'Bokeh'], 'Geniş diyaframda ve geniş açıda ışık kenarlara zayıf ulaştığından köşeler kararır.'),
  ('Düz çizgilerin kadrajın kenarlarında dışa doğru bombeli görünmesine yol açan objektif hatasına ne denir?', 'Fıçı distorsiyonu', ['İğne yastığı distorsiyonu', 'Koma', 'Küresel sapma'], 'Geniş açı ve balık gözü objektiflerinde yaygın olan bu sapmada görüntü merkezden uzaklaştıkça bombeleşir.'),
  ('Parlak noktaların odak dışı bulanıklığının nasıl göründüğünü anlatan ve diyafram bıçaklarının biçiminden etkilenen terim hangisidir?', 'Bokeh', ['Vinyetleme', 'Moiré', 'Aberasyon'], 'Bokeh, odak dışı alanın estetik niteliğini anlatır; diyafram bıçakları yuvarlaksa parlak noktalar daha yuvarlak görünür.'),
  ('Odak uzaklığı sabit tutulup diyafram f/8\'den f/2.8\'e açıldığında alan derinliği nasıl değişir?', 'Azalır', ['Artar', 'Değişmez', 'Önce artar sonra azalır'], 'Diyafram açıldıkça odak dışı alanlar daha belirgin bulanıklaşır; netlik bölgesi daralır.'),
  ('Panning (kamera takibi) tekniğinde fotoğrafçı hareketli konuyla birlikte makineyi yatay çevirirken uzun bir enstantane (örneğin 1/30 saniye) kullanırsa ne elde eder?', 'Konu nispeten net, arka plan yatay çizgilerle bulanık', ['Konu bulanık, arka plan net', 'Hem konu hem arka plan tamamen donmuş ve konunun arkaya akması', 'Tüm kare karanlık'], 'Makine konuyla aynı hızda döndüğü için konu görece sabit kalır; arka plan ise ters yönde akıp hareket duygusu verir.'),
  ('Işıkla boyama (light painting) tekniğinde fotoğrafçı çoğunlukla nasıl çalışır?', 'Karanlıkta uzun pozlama yapıp el fenerleriyle ışık izleri çizer', ['Gün ışığında çok kısa pozla çeker', 'Stüdyo flaşıyla hareketi dondurur', 'Elle çizilmiş bir fotoğrafı tarar'], 'Deklanşör açıkken ışık kaynakları hareket ettirilir; ışık izleri uzun pozlama sırasında sensörde çizgi olarak birikir.'),
  ('Bir fotoğrafçı çekim sırasında zum halkasını çevirerek merkezden dışarı yayılan çizgiler elde ediyor. Bu yönteme ne denir?', 'Zum patlaması', ['Panning', 'Odak yığınlama ve çoklu pozlama birleştirmesi', 'Uzun pozlamayla ışık boyama'], 'Uzun enstantane süresince odak uzaklığı değiştirildiği için görüntü merkezden dışa doğru ışınsal biçimde akar.'),
  ('Kasıtlı kamera hareketi (ICM) tekniğinde fotoğrafçı uzun enstantaneyle makineyi dikey çekerse ormandaki ağaç gövdeleri nasıl görünür?', 'Boyayla çizilmiş gibi yumuşak dikey akışlar', ['Tam keskin dik çizgiler', 'Yatay şeritler', 'Renkler tamamen siyaha döner ve görüntünün tamamen netleşmesi'], 'Makinenin ağaçlarla aynı yönde süpürülmesi, ayrıntıyı eriterek resimsel ve soyut bir doku yaratır.'),
  ('Aynı kareye birden çok pozlamayı birleştirmenin (çoklu pozlama) film çağındaki en basit uygulaması nedir?', 'Aynı film karesini deklanşörü sarmadan iki ya da daha çok kez çekmek', ['Filmi iki kez banyo etmek', 'Negatifi cam levha üzerine basmak', 'Film hızını yarıya indirmek'], 'Filmin ilerlemesi durdurulduğunda ya da sarılmadığında aynı kareye iki görüntü üst üste kaydolur.'),
  ('Bir yıldız izi (star trail) fotoğrafında yıldızların gökte daireler çizmesi hangi olayın sonucudur?', 'Dünya\'nın kendi ekseni etrafında dönmesi', ['Yıldızların Dünya çevresinde dönmesi', 'Makinenin sarsılması', 'Atmosferin yıldızları yerinden oynatması, bu da gözlemci açısından görünümü bozar'], 'Dünya saatte yaklaşık 15 derece döndüğü için uzun pozlamada yıldızlar kutup yıldızı çevresinde yay çizer.'),
  ('Bulutların akışı ya da bir çiçeğin açması gibi uzun süren değişimi kısa bir videoda hızlandırılmış göstermek için hangi teknik kullanılır?', 'Zaman atlamalı (time-lapse)', ['Yarım ton (raster) (yarım ton baskı yöntemi)', 'Kontakt baskı', 'Fotogram'], 'Belirli aralıklarla çekilen çok sayıda kare art arda oynatılınca uzun süreçler kısa bir videoda hızlanmış görünür.'),
  ('Havai fişek çekimlerinde en uygun enstantane yaklaşık hangi aralıktadır?', 'Birkaç saniye', ['1/1000 saniye', '1/125 saniye', '1/4000 saniye'], 'Fişeğin yükseliş ve patlama iziyle gökte oluşturduğu çizgiler ancak birkaç saniyelik pozla görüntüde birikir.'),
  ('Flaşlı çekimde yavaş enstantane (sürükleme, drag shutter) kullanmak neyi sağlar?', 'Konuyu flaşla dondurup arka plandaki ortam ışığını da yakalamayı', ['Flaşı tamamen kapatmayı', 'Görüntüyü siyah beyaza çevirmeyi', 'Hareketi sürekli dondurmayı'], 'Uzun enstantane ortam ışığını arka plana yansıtır; flaş ise konuyu net aydınlatır, böylece arka plan karanlık kalmaz.'),
  ('Araçların far ve stop ışıklarının gece uzun pozlamada çizgi olarak görünmesinin nedeni nedir?', 'Işık kaynağı pozlama süresince sensörde yer değiştirerek iz bırakır', ['Farların gerçekte çizgi olması', 'Lens çizgi oluşturması', 'Makinenin sarsılması'], 'Hareketli ışığın izi, deklanşör açıkken sürekli kaydedilir ve yol boyunca bir çizgi çizer.'),
  ('Fotoğraf makinesinin deklanşör süresinden daha hızlı hareket eden bir konunun net çıkması için hangi yöntem dolaylı yoldan kullanılır?', 'Çok kısa süreli flaş patlaması', ['Çok yüksek diyafram ve hiç flaş kullanmamak', 'Çok uzun enstantane', 'Düşük ISO'], 'Flaş ışığı çok kısa sürdüğünden hareketli konu o anda dondurulur; Edgerton\'ın stroboskopu bu fikre dayanır.'),
  ('Yıldızlı gökyüzünü tripot olmadan çekmek zorunda kalan bir fotoğrafçı ISO\'yu çok yükseltirse hangi sonuç beklenir?', 'Kısa pozla net kare, ama belirgin gürültü', ['Daha temiz ve daha keskin görüntü ve renkli bir görüntü', 'Renklerin tamamen soluklaşması', 'Yıldız izlerinin uzaması'], 'ISO arttıkça kısa pozlama yeterli olur; ancak yüksek ISO sensör gürültüsünü de artırır.'),
  ('Fotoğraf makinelerindeki "bulb" (B) modunu kullanmak uzun pozlama için hangi avantajı sağlar?', 'Enstantane süresini deklanşöre basılı tutarak serbestçe belirlemek', ['Otomatik odağı kapatmak', 'Işık ölçümü yapmak', 'Flaşı şarj etmek'], 'Bulb modunda perde, deklanşör basılı kaldığı sürece açık kalır; böylece 30 saniyenin üzerinde sınırsız pozlama yapılabilir.'),
  ('Bir fotoğrafçı kalabalık bir meydanı gün ışığında 30 saniye pozlayabilmek için ne yapmalıdır?', 'Güçlü ND filtre takıp tripot kullanmalıdır', ['Diyaframı sonuna kadar açmalıdır ve flaşla desteklemelidir', 'ISO\'yu 6400 yapmalıdır', 'Flaş kullanmalıdır'], 'Gün ışığı çok parlak olduğundan uzun pozlama için ışığı yüksek oranda azaltan ND filtre gerekir; kalabalık yarı saydam bir sis gibi akar.'),
  ('Büyük format görüntü makinesinde (view camera) buğulu cam üzerinde oluşan görüntünün özelliği nedir?', 'Yukarıdan aşağıya ve soldan sağa ters çevrilmiştir', ['Yalnızca siyah beyazdır', 'Her zaman gerçek boyutundadır ve görüntünün renkli oluşu', 'Hiçbir ayrıntı göstermez'], 'Objektifin oluşturduğu görüntü buğulu camda baş aşağı ve ters belirir; bu yüzden fotoğrafçı karanlık bez altında odaklar.'),
  ('Büyük formatlı makinede 4 × 5 inç boyutundaki tek tek levha film nasıl yüklenir?', 'Işık geçirmez film tutucuya ve kızıl ışıkta ya da karanlıkta', ['Gün ışığında rulo hâlinde', 'Doğrudan sensör üzerine', 'Cam levha yerine banyo kabına'], 'Her tutucuda iki levha bulunur; kapaklar çekilip pozlama yapıldıktan sonra yeniden kapatılır.'),
  ('Scheimpflug ilkesine göre film düzlemi, objektif düzlemi ve odaklanılan konu düzlemi nasıl bir ilişki içindedir?', 'Üçü de ortak bir doğru üzerinde kesişir', ['Üçü de birbirine paraleldir', 'Film ve objektif paraleldir, konu düzlemi dik açıdadır', 'Üçü de aynı noktada ve aynı yönde bulunur'], 'Bu ilke, düzlemlerin kesişim çizgisi sayesinde odak düzleminin eğilip yer yüzeyi gibi eğik yüzeylerde netlik sağlamasını açıklar.'),
  ('Büyük format negatiflerin küçük formatlı filmlere göre başlıca üstünlüğü nedir?', 'Daha büyük yüzey sayesinde daha çok ayrıntı ve ince taneli baskı', ['Daha ucuz olması', 'Daha hafif makinelerle kullanılması', 'Elde çekime elverişli olması'], 'Büyük negatif aynı baskı boyutuna daha az büyütmeyle ulaştığından incelik ve ton geçişleri korunur.'),
  ('Platin ve paladyum baskının öteki yöntemlere göre en belirgin özelliği nedir?', 'Çok geniş ton aralığı ve kâğıda gömülü, mat, kalıcı görüntü', ['Parlak jelatinli yüzey', 'Mavi tonlu görüntü', 'Hızlı ve ucuz banyo'], 'Metal tuzlarına dayalı bu kontakt baskı, derin ve ince tonlu sonuç verir; platin kâğıt üzerinde silinmez bir görüntü oluşturur.'),
  ('Talbot\'un ilk dönemlerinde kullandığı, kâğıt yüzeyini tuz ve gümüş nitratla duyarlı kılan baskı türü hangisidir?', 'Tuzlu kâğıt (salt print) baskısı', ['Albümin baskı ve camdan yapılmış kayıt biçimi', 'Siyanotip', 'Karbon baskı'], 'Tuzlu kâğıt baskı, jelatinsiz, mat bir yüzeyle kâğıt liflerine işlenmiş yumuşak bir görüntü verir.'),
  ('Karbon (carbon) baskı ile elde edilen görüntü neden son derece kalıcıdır?', 'Gümüş yerine kararmayan pigmentli jelatin kullanılması', ['Kâğıdın metal olması', 'Baskıdan sonra yüzeyin boyanması ve sonradan elle boyanması', 'Camdan yapılması'], '1864\'te Swan\'ın geliştirdiği yöntem, pigmentli jelatinin ışıkla sertleşmesine dayanır; gümüşle solma sorunu yoktur.'),
  ('Bromoil (bromür-yağ) baskı tekniğinde ressamsı etki nasıl elde edilir?', 'Ağartılmış bromür baskı üzerine yağlı mürekkep fırçayla uygulanır', ['Baskı üzerine renkli cam yerleştirilir', 'Film yağda yıkanır', 'Görüntü kâğıda kazınır'], 'Jelatinin sertleştiği alanlar mürekkep tutar; fotoğrafçı fırça ile görüntüyü elle yorumlayabilir.'),
  ('Gravür plakasına fotoğrafı bakır üzerine asitle işleyerek kitap basımı için çoğaltmaya yarayan yöntem hangisidir?', 'Fotogravür', ['Fotogram', 'Kolodyon', 'Solarizasyon'], 'Camera Work gibi kaliteli dergilerde kullanılan fotogravür, fotoğrafın ton geçişlerini mürekkepli baskıya taşır.'),
  ('Cam levhanın duman karasıyla kaplanıp üzerinin çizilmesi ve ışığa duyarlı kâğıda baskı yapılmasıyla elde edilen yöntem hangisidir?', 'Clichê-verre', ['Autochrome', 'Kalotip', 'Fotokrom'], 'Corot ve Daubigny gibi sanatçılar, cam üzerine çizim yapıp fotoğraf kâğıdına basarak "klişe-cam" ürünleri üretmiştir.'),
  ('Islak kolodyon (tintip) fotoğrafçısı neden yanında taşınabilir bir karanlık oda kullanmak zorundaydı?', 'Levhanın hazırlanıp çekilip banyo edilmesi kolodyon kurumadan yapılmalıydı', ['Karanlıkta pozlanması gerektiği için', 'Makine ışığa duyarsız olduğu için', 'Yasalar böyle zorunlu kıldığı için'], 'Kolodyon kuruyunca ışığa duyarlılığını kaybettiğinden, çekimden banyoya kadar iş on dakika içinde bitirilmelidir.'),
  ('Van Dyke kahverengi baskının sepya tonlu görüntüsü hangi tür duyarlı kimyasaya dayanır?', 'Demir ve gümüş tuzlarına', ['Platin tuzlarına ve ışığa duyarsız kâğıtlar', 'Bitümlü asfalta', 'Bikromatlı zamka'], 'Bu yöntem demir tuzlarının ışıkla indirgenip gümüşe dönüşmesine dayanır ve kahverengi bir görüntü verir.'),
  ('Bir fotoğrafçı, negatifi kâğıda doğrudan temas ettirip ışıkla basıyor; makine ve büyütme yok. Bu yöntemin adı nedir?', 'Kontakt baskı', ['Projeksiyon baskısı', 'Büyütme baskısı', 'Pozitif film'], 'Kontakt baskıda görüntü boyutu negatifle aynıdır; bu yüzden büyük format negatifler gerekir.'),
  ('Karanlık odada fotoğraf kâğıdına asıl baskıdan önce şeritler hâlinde farklı sürelerle pozlama yapılmasının amacı nedir?', 'En uygun baskı süresini deneyle belirlemek', ['Kâğıdın boyutunu ölçmek', 'Negatifi temizlemek', 'Banyonun sıcaklığını ayarlamak ve kâğıdın boyutunu doğrulamak'], 'Aynı kâğıdın her şeridi farklı süre ışık alır; banyodan sonra en iyi tonlu şerit seçilerek asıl baskı süresi bulunur.'),
  ('36 mm genişliğindeki negatiften 30 cm genişliğinde baskı elde etmek için büyütme oranı yaklaşık kaçtır?', '8,3 kat', ['3,6 kat', '12 kat', '30 kat'], 'Büyütme = 300 mm ÷ 36 mm yaklaşık 8,3\'tür.'),
  ('Siyah beyaz değişken kontrastlı kâğıtta macenta filtre kullanımı baskıda nasıl bir etki yapar?', 'Kontrastı artırır', ['Kontrastı azaltır', 'Baskıyı tamamen kırmızıya boyar', 'Görüntüyü negatife çevirir'], 'Macenta filtre, yüksek kontrastlı katmanı çalıştırır; sarı filtre ise düşük kontrastlı katmanı.'),
  ('Kontrast derecesi 0\'dan 5\'e doğru artan kâğıt gruplarında yüksek bir dereceye geçmek baskıda neyi değiştirir?', 'Siyahlar ile beyazlar arasındaki geçişi sertleştirir, gri tonlar azalır', ['Her tonu gri yapar', 'Görüntüyü bulanıklaştırır', 'Baskıyı renklendirir'], 'Yüksek kontrast dereceleri, negatifin düz kalmış tonlarını ayırır, ama ara tonları sıkıştırır.'),
  ('Siyah beyaz kâğıtla çalışırken karanlık odada amber ya da kırmızı güvenli ışık (safelight) kullanılmasının nedeni nedir?', 'Kâğıt bu renklere duyarsızdır ve görüntü bozulmaz', ['Kâğıt yalnızca kırmızı ışıkla pozlanır ve kâğıt yalnızca amber ışığa duyarlıdır', 'Işık negatifi temizler', 'Banyoyu hızlandırır'], 'Siyah beyaz baskı kâğıdı mavi-yeşile duyarlı, kırmızıya duyarsızdır; bu yüzden güvenli ışık altında işlenebilir.'),
  ('Film banyosunda geliştiriciden sonra konan durdurucu (stop) banyonun, çoğunlukla seyreltik asetik asit, görevi nedir?', 'Geliştirmeyi hızla durdurup sabitleyiciyi korumak', ['Filmi renklendirmek', 'Gümüşü çözmek', 'Negatifi kurutmak'], 'Asidik durdurucu, alkali geliştiriciyi nötrler; böylece geliştirme kontrollü biçimde biter ve sabitleyici bozulmaz.'),
  ('Film geliştirmede sıcaklık aniden büyük ölçüde değişirse emülsiyonda buruşma ve ağ biçimli çatlaklar oluşabilir. Bu duruma ne denir?', 'Retikülasyon', ['Solarizasyon', 'Vinyetleme', 'Halo'], 'Çözeltiler arasında ani sıcaklık farkı jelatinin şişip kırışmasına yol açar.'),
  ('Reçine kaplı (RC) kâğıtlar fiber tabanlı (FB) kâğıtlara göre hangi özelliğiyle bilinir?', 'Daha hızlı yıkanıp kurur', ['Daha uzun ömürlü olması', 'Daha zengin tonlu olması', 'Daha kalın ve ağır olması'], 'Plastik tabaka suyu geçirmediği için RC kâğıt dakikalar içinde yıkanıp kurur; FB kâğıt ise saatlerce yıkama ister.'),
  ('Seleniyum toner siyah beyaz baskıya ne katar?', 'Daha koyu siyahlar ve daha kalıcı bir görüntü', ['Mavi bir ton', 'Daha düşük kontrast', 'Daha yumuşak odak'], 'Seleniyum, gümüşü kısmen selenürlü gümüşe çevirip derinleştirir ve baskıyı çevresel etkilere karşı korur.'),
  ('Baskıların kurumadan sonra hafifçe koyulaşması durumuna ne ad verilir?', 'Kuruma kararması', ['Retikülasyon', 'Vinyetleme', 'Yıkama lekesi ve baskıya sararmış leke bırakması'], 'Islak baskıda yansıma ışığı yüzeyde fazla göründüğünden baskı kuruyunca biraz koyulaşır.'),
  ('Büyütücü objektifinde en iyi keskinlik için genellikle hangi diyafram kullanılır?', 'En geniş açıklıktan iki üç durak kısılmış', ['En geniş açıklık', 'En dar diyafram', 'Her diyafram aynıdır'], 'Orta diyaframlar aberasyonu azaltır ve kırınımı artırmadığı için en keskin görüntüyü verir.'),
  ('Renkli baskıda büyütücü başlığındaki dikroik filtrelerin (sarı, macenta, camgöbeği) amacı nedir?', 'Işığın rengini ayarlayıp baskıdaki renk dengesini düzeltmek', ['Film hızını artırmak', 'Karanlık odayı aydınlatmak', 'Negatifi temizlemek'], 'Subtraktif renk filtreleri ışık karışımını değiştirerek renk baskıdaki dominant tonları düzeltir.'),
  ('Renkli negatif film (C-41) ile renkli slayt filmi (E-6) arasındaki fark, hangi işlemle ilişkili olarak ayırt edilir?', 'Banyo kimyasalları ve sonuç', ['Filmin format büyüklüğü', 'Işık ölçüm şekli', 'Yalnızca fiyatları'], 'C-41 renkli negatif, E-6 ise doğrudan pozitif slayt üretir; bu yüzden işlem kimyasalları farklıdır.'),
  ('Baskı üzerinde toz izlerinin ince fırça ve boyayla örtülmesine ne ad verilir?', 'Spotlama (spotting)', ['Tonlama', 'Sabitleme (kâğıdı ışığa dayanıklı kılma)', 'Yarım ton'], 'Baskı kurudukça beyaz lekeler ince fırçayla boyanır; böylece toz izi gibi hatalar görünmez olur.'),
  ('Kontak sayfanın fotoğraf çekiminden sonra başlıca işlevi nedir?', 'Bütün karelere hızla bakıp basılacak kareleri seçmek', ['Baskıyı kalıcı kılmak', 'Negatifi korumak', 'Banyoyu hızlandırmak'], 'Kontak sayfa her kareyi küçük bir pozitif olarak gösterir; fotoğrafçı büyütmeden önce seçimini yapar.'),
  ('Dijital makinelerde CMOS sensörün CCD sensöre göre günümüzde daha yaygın olmasının nedenlerinden biri hangisidir?', 'Her pikselin kendi yükselticisi olduğundan hızlı okunması ve düşük güç tüketmesi', ['Işığı hiç algılamaması', 'Yalnızca siyah beyaz görüntü vermesi', 'Film kullanımına benzemesi'], 'CMOS, pikselde sinyali dönüştürerek hızlı seri çekime, video çekimine ve düşük enerji tüketimine elverişlidir.'),
  ('Bir sensörün her pikselindeki fotodiyotun ışığa karşı davranışı nasıldır?', 'Gelen foton sayısıyla orantılı elektrik yükü biriktirir', ['Gelen ışığın rengini doğrudan ölçer ve ışığın dalga boyunu ölçer', 'Işığı fotoğraf kâğıdına yansıtır', 'Işığı kimyasal olarak kaydeder'], 'Fotodiyot yalnızca ışık miktarını ölçer; renk bilgisi önündeki renk filtrelerinden gelir.'),
  ('Bayer filtreli bir sensörde her pikselin yalnızca bir rengi kaydetmesine rağmen tam renkli görüntü nasıl elde edilir?', 'Komşu piksellerden eksik renklerin hesaplanmasıyla', ['Her piksel üç kez çekim yapar', 'Filtre sonradan çıkarılır', 'Fotoğraf kâğıdı renkleri tamamlar'], 'Demozaikleme algoritması, komşu piksellerin değerlerinden her pikselin eksik iki rengini tahmin eder.'),
  ('Optik alçak geçiren (anti-aliasing) filtrenin kaldırıldığı sensörlerde ince desenli kumaş çekilirken ne tür bir sorunla karşılaşılabilir?', 'Moiré (girişim deseni)', ['Kırmızı göz ve renk sapması (sarı ton)', 'Vinyetleme', 'Bokeh'], 'Sensörün piksel dizisi ile ince desenin tekrar frekansı çakışınca dalgalı yapay desenler belirir.'),
  ('Bir sensörde piksel boyutu büyüdükçe, aynı sensör alanı ve çekim koşulunda hangi sonuç beklenir?', 'Her piksel daha çok ışık toplar ve gürültü azalır', ['Her piksel daha az ışık toplar ve kaydedilen sinyal gürültüsü artar', 'Renkler kaybolur', 'Odak uzaklığı değişir'], 'Daha büyük piksel daha çok foton toplar; sinyal-gürültü oranı artar, özellikle düşük ışıkta fark edilir.'),
  ('Her renk kanalı için 8 bit kullanılan bir RGB görüntüde toplam kaç farklı renk gösterilebilir?', 'Yaklaşık 16,7 milyon', ['Yaklaşık 256', 'Yaklaşık 65 bin', 'Yaklaşık 4 milyar ve 8 bit için doğru bir değer'], 'Her kanalda 256 düzey bulunur; 256³ = 16.777.216 renk elde edilir.'),
  ('14 bit RAW dosyada bir kanal kaç farklı parlaklık düzeyi kaydeder?', '16.384', ['1.024', '4.096', '65.536'], '2^14 = 16.384; 8 bitlik JPEG\'in yalnızca 256 düzeyine kıyasla çok daha ince tonlama sağlar.'),
  ('6000 × 4000 piksel çözünürlükteki sıkıştırılmamış, 8 bitlik RGB bir görüntünün yaklaşık dosya boyutu kaç megabayttır?', '72 MB', ['24 MB', '12 MB', '144 MB'], '24 milyon piksel × 3 bayt (R, G, B) = 72 milyon bayt, yani yaklaşık 72 MB.'),
  ('Bir fotoğraf 6000 × 4000 piksel ise 300 ppi\'de kaç santimetre genişliğinde basılabilir?', 'Yaklaşık 50,8 cm', ['Yaklaşık 20 cm', 'Yaklaşık 15 cm', 'Yaklaşık 100 cm'], '6000 ÷ 300 = 20 inç = 20 × 2,54 = 50,8 cm.'),
  ('Mobil telefon kameralarında fotoğraf yapılırken küçük sensörün başlıca sonucu nedir?', 'Alan derinliği çok geniştir ve arka plan zor bulanıklaşır', ['Alan derinliği çok dardır', 'Gürültü hiç yoktur', 'Renkler kaybolur'], 'Küçük sensörlerde objektifin odak uzaklığı kısa olduğundan alan derinliği geniştir; yapay bulanıklık için yazılımdan yararlanılır.'),
  ('Akıllı telefonlardaki "portre modu" arka planı bulanık göstermek için en çok hangi yöntemden yararlanır?', 'Derinlik haritasını tahmin edip yazılımla bulanıklaştırır', ['Daha büyük diyafram açar', 'Işığı kırmızıya boyar', 'Flaş kullanır'], 'İki kamera ya da algoritma derinlik tahmini üretir; arka plan yazılımla yapay olarak bulanıklaştırılır.'),
  ('Gece modu özelliği olan telefonların düşük ışıkta daha temiz fotoğraf elde etmesinin temelinde ne yatar?', 'Birçok kısa pozlu karenin hizalanıp birleştirilmesi', ['Çok yüksek ISO ile tek çekim', 'Büyük sensörle uzun poz', 'Flaşın gücünü artırma'], 'Çoklu kare birleştirme, gürültüyü ortalama yoluyla azaltır ve ayrıntıyı korur; buna hesaplamalı fotoğrafçılık denir.'),
  ('Dijital sensörlerde "rolling shutter" etkisi hızlı hareket eden bir konuda nasıl görünür?', 'Çarpık, yan yatmış görünüm', ['Renk kaybı', 'Çift görüntü', 'Flaş yansıması ve renklerin ters dönmesi'], 'Sensör satırları sırayla okunduğundan hareket eden konuda satırlar farklı anlarda kaydedilir; dik çizgiler eğilir.'),
  ('Dijital fotoğrafta histogramın sağ kenarına dayanıp kesilmesi ne anlama gelir?', 'Parlak alanlarda bilgi kaybı', ['Gölgelerin ayrıntılı olması ve renklerin soluklaşması', 'Renk doygunluğunun artması', 'Doğru pozlama'], 'Sağ kenar parlak tonları gösterir; oraya yığılma, bu alanların beyaza kesilip ayrıntı kaybettiğini belirtir.'),
  ('sRGB ve Adobe RGB renk uzayları karşılaştırıldığında hangisi doğrudur?', 'Adobe RGB, özellikle yeşil-camgöbeği alanında daha geniş renk aralığı kapsar', ['sRGB, Adobe RGB\'den daha geniş renk aralığı kapsar', 'İkisi tamamen aynıdır', 'sRGB yalnızca siyah beyaz içindir'], 'Web için sRGB standarttır; Adobe RGB baskı iş akışlarında daha geniş renk için kullanılır.'),
  ('Kayıpsız bir dosya biçiminin kayıplı olandan farkı nedir?', 'Yeniden kaydedildiğinde piksel bilgisi bozulmaz', ['Dosya her zaman daha küçüktür ve renkleri soldurması', 'Renkler daha çok doygundur', 'Yalnızca videoda kullanılır'], 'PNG ve TIFF gibi biçimler görüntüyü bire bir saklar; JPEG ise ayrıntıyı atarak boyutu küçültür.'),
  ('JPEG sıkıştırmasında yüksek sıkıştırma oranlarında görüntüde hangi belirgin kusur görülür?', 'Sekiz piksellik bloklar hâlinde kareli bozulmalar', ['Görüntünün ters dönmesi', 'Siyah beyaza dönmesi', 'Piksel sayısının artması'], 'JPEG, görüntüyü 8 × 8 bloklara ayırıp keserek sıkıştırdığından yüksek sıkıştırmada blok kenarları belirir.'),
  ('Fotoğrafın EXIF verisinde genellikle hangi bilgiler yer alır?', 'Makine modeli, enstantane, diyafram, ISO ve çekim zamanı', ['Fotoğrafçının e-posta şifresi', 'Baskı kâğıdının cinsi', 'Karanlık oda kimyasalları'], 'EXIF, dosyaya gömülen çekim bilgisidir; bazı makineler GPS konumunu da kaydeder.'),
  ('Panoramik birleştirmede (stitching) başarılı sonuç için ardışık karelerin ne kadar örtüşmesi önerilir?', 'Yaklaşık %30', ['%0', '%90', '%100'], 'Yaklaşık üçte bir örtüşme, yazılımın ortak noktaları bulup perspektif farkını düzeltmesine yeter.'),
  ('Dijital fotoğrafta düşük ışıkta uzun pozlama sonrasında görülen ve sensör ısındıkça artan parlak noktalara ne denir?', 'Sıcak pikseller', ['Moiré', 'Bokeh', 'Vinyet ve görüntünün köşelerinin kararması'], 'Isınan sensör bazı piksellerde sahte sinyal yaratır; uzun pozlama gürültü azaltma, karanlık kare çıkararak bunları giderir.'),
  ('Fotoğraf yazılımlarında "keskinleştirme" (sharpening) işlemi görüntü üzerinde aslında ne yapar?', 'Kenarlarda kontrastı artırarak daha net izlenim yaratır', ['Kaybolan ayrıntıyı geri getirir', 'Pikselleri çoğaltır', 'Odağı düzeltir'], 'Keskinleştirme, açık-koyu geçişlerini vurgulayıp netlik hissi verir; ancak olmayan ayrıntıyı eklemez.'),
  ('Bir fotoğrafın çözünürlüğünü yazılımla büyütmek (yeniden örnekleme) neden gerçek ayrıntı eklemez?', 'Yazılım yalnızca var olan pikseller arasında tahmini değerler ekler', ['Yazılım gerçek ayrıntıyı bulup ekler', 'Sensör aniden büyür', 'Işık artar'], 'Büyütme, yeni pikselleri komşu değerlerden hesaplar; yeni bilgi kazandırmaz.'),
  ('Fotoğrafta "dinamik aralık" terimi neyi anlatır?', 'Sensörün kaydedebildiği en karanlık ve en parlak tonlar arasındaki aralığı', ['Makinenin saniyedeki kare sayısını', 'Objektifin odak mesafesini', 'Flaşın gücünü'], 'Dinamik aralık durak cinsinden ifade edilir; geniş aralık hem gölge hem parlak bölgede ayrıntı korur.'),
  ('Letizia Battaglia\'yı fotoğraf tarihinde anılır kılan çalışma alanı nedir?', 'Palermo\'da mafya cinayetlerinin ve kentin yaşamının belgelenmesi', ['Moda çekimleri', 'Doğa fotoğrafçılığı', 'Reklam fotoğrafı'], 'Battaglia, Sicilya\'da L\'Ora gazetesi için mafya cinayetlerini çekerek şiddetin toplum yaşamındaki yerini gözler önüne sermiştir.'),
  ('Sualtı fotoğraflarında derinlik arttıkça görüntünün mavi-yeşile kaymasının nedeni nedir?', 'Suyun kırmızı ışığı ilk emmesi', ['Suyun mavi ışığı yansıtmaması ve yüzeyde parlak olması', 'Makinenin sensör hatası', 'Işığın yukarıdan gelmesi'], 'Su, uzun dalga boylarını, yani kırmızı ve turuncuyu birkaç metrede soğurur; derinde geriye mavi ve yeşil kalır.'),
  ('Sualtı fotoğrafçısının makinesini düz cam portlu muhafazaya koyduğunda su içinde nesneler gözle nasıl görünür?', 'Yaklaşık dörtte bir daha yakın ve daha büyük', ['Yarı yarıya daha uzak', 'Aynı boyutta ve aynı uzaklıkta ve daha küçük görünür', 'Ters çevrilmiş'], 'Suyun kırılma indisi (yaklaşık 1,33) yüzünden nesneler yaklaşık üçte bir büyük görünür ve görüş açısı daralır.'),
  ('Adli fotoğrafçılıkta suç mahallinde ayak izi ya da alet izi çekilirken izin yanına cetvel konmasının amacı nedir?', 'Fotoğrafı sonradan ölçeklendirip gerçek boyutuna ulaşmak', ['Fotoğrafa süs vermek', 'İzi silmek', 'Işığı azaltmak'], 'Cetvel, fotoğraftaki boyutların gerçek değerlerle karşılaştırılmasını sağlayan bir referans oluşturur.'),
  ('Adli fotoğrafçılıkta toprak ya da kum üzerindeki ayak izini belirginleştirmek için ışık nasıl kullanılır?', 'Yandan eğik ışıkla', ['Doğrudan öndeki flaşla', 'Ortam ışığını tamamen kapatarak', 'Yalnızca gökyüzü ışığıyla'], 'Yandan gelen eğik ışık, yüzey kabartılarının gölgelerini uzatarak izi görünür kılar.'),
  ('19. yüzyıl Avrupa ve Amerika\'sında ölen sevdiklerin fotoğraflarının çektirilmesi geleneğine ne ad verilir?', 'Ölüm sonrası (post-mortem) fotoğrafçılığı', ['Siluet portre', 'Kartvizit portre', 'Panoramik fotoğraf'], 'Fotoğraf pahalı olduğu için çoğu ailenin tek yadigârı olan bu portreler, ölüyü uyuyor gibi poz vererek çekilirdi.'),
  ('Makro fotoğrafta "1:1 üreme oranı" ne anlama gelir?', 'Nesnenin sensörde gerçek boyutuyla görüntülenmesi', ['Nesnenin yarı boyutunda görüntülenmesi ve görüntünün küçülmesi gerektiği', 'İki kat büyütülmesi', 'Odak uzaklığının iki katı olması'], '1:1 oran, 10 mm\'lik bir nesnenin sensörde 10 mm\'lik görüntü oluşturması demektir.'),
  ('Kızılötesi filmle çekilen manzaralarda yaprakların beyaz parlak, gökyüzünün koyu görünmesine yol açan olaya ne ad verilir?', 'Wood etkisi', ['Moiré', 'Solarizasyon', 'Albedo'], 'Klorofil kızılötesi ışığı yansıttığından yapraklar açık tonda çıkar; buna 1910\'larda tanımlayan Robert W. Wood\'un adı verilmiştir.'),
  ('Dönen bir mekanizmayla çok geniş panoramalar çekmek için kullanılan, grup fotoğraflarında yaygın makine türü hangisidir?', 'Cirkut kamerası', ['Speed Graphic', 'Leica', 'Rolleiflex'], 'Cirkut, makineyi ve filmi birlikte döndürerek yüzlerce derecelik tek bir görüntü elde eder.'),
  ('Mimari fotoğrafçılıkta geniş açılı objektif kullanıldığında kenarlarda hangi sorun belirginleşir?', 'Perspektif bozulması ve yakınsayan dikey çizgiler', ['Odak kayması', 'Renk körlüğü', 'Flaş yansıması'], 'Geniş açı kenarlara doğru nesneleri esnetir; makine eğikse dikey çizgiler birbirine yakınsar.'),
  ('Ürün fotoğrafçılığında parlak bir metal nesnedeki istenmeyen yansımaları azaltmak için hangi araç yaygındır?', 'Işık çadırı ve yumuşak kutu', ['Çıplak flaş', 'Işığı doğrudan yöneltmek ve doğrudan flaşla yüzeyi aydınlatmak', 'Siyah fon'], 'Parlak yüzey çevresindeki her şeyi yansıttığından, geniş ve yumuşak ışık kaynakları ya da ışık çadırı yansımaları kontrol eder.'),
  ('Mikroskop altındaki bir hücreyi renkli göstermek için fotoğrafçılar bazen yapay renkli görüntüler üretirler. Bu renklendirmenin başlıca amacı nedir?', 'Farklı yapıları ayırt etmeyi kolaylaştırmak', ['Gerçek rengi göstermek ve ışığı artırarak canlandırmak', 'Hücreyi canlandırmak', 'Işığı artırmak'], 'Bilimsel görüntülerde sahte renk, yapıların ve yoğunlukların daha net ayırt edilmesini sağlar.'),
  ('200 mm f/2.8 telefoto objektifin ön açıklığının (giriş gözbebeği) çapı yaklaşık kaç mm\'dir?', 'Yaklaşık 71 mm', ['Yaklaşık 28 mm', 'Yaklaşık 560 mm', 'Yaklaşık 20 mm'], 'f sayısı = odak uzaklığı ÷ açıklık çapı olduğundan çap = 200 ÷ 2,8 yaklaşık 71 mm\'dir.'),
  ('Tam karede 50 mm objektifin yatay görüş açısı yaklaşık kaç derecedir?', 'Yaklaşık 40 derece', ['Yaklaşık 20 derece', 'Yaklaşık 75 derece', 'Yaklaşık 100 derece'], 'Yatay görüş açısı 2 × arctan(18/50) yaklaşık 39,6 derece eder.'),
  ('Aynı sensörde 24 mm yerine 85 mm objektife geçildiğinde görüş açısı hangi yönde değişir?', 'Belirgin biçimde daralır', ['Genişler', 'Değişmez', 'Önce genişleyip sonra daralır'], 'Odak uzaklığı arttıkça görüş açısı azalır; 85 mm\'de yatay açı yaklaşık 24 derecedir.'),
  ('Kamera obscura görüntüsünü keskinleştirmek için deliği küçültmek hangi sonuca yol açar?', 'Görüntü keskinleşir ama daha az ışık geçer', ['Görüntü parlaklaşır', 'Görüntü ters döner', 'Görüntü renklenir'], 'Küçük delik her noktadan gelen ışığı dar bir demetle sınırlar; keskinlik artar, parlaklık azalır.'),
  ('Fotoğraf makinesinin objektifindeki asferik elemanların temel amacı nedir?', 'Küresel sapmayı ve distorsiyonu azaltmak', ['Renk sıcaklığını ayarlamak ve flaş yansımasını önlemek', 'Flaşı kontrol etmek', 'Görüntüyü ters çevirmek'], 'Küre dışı bir eğri, ışınları daha iyi tek noktada toplayarak geniş açıklıkta keskinliği artırır.'),
  ('Çok düşük ışıkta fotoğraf makinesinin sensöründe rastgele renkli lekeler görünmesinin temel nedeni nedir?', 'Zayıf sinyalin yükseltilirken gürültünün de artması', ['Işığın çok parlak olması', 'Objektifin kirlenmesi', 'Sensörün ısınmaması'], 'ISO arttıkça sinyal yükseltilir; rastgele elektronik ve foton gürültüsü de aynı oranda belirginleşir.'),
  ('Capa takma adı hakkında hangisi doğrudur?', 'Endre Friedmann ile Gerda Taro\'nun yarattığı kurgu bir Amerikalı fotoğrafçı kimliğiydi', ['Capa\'nın gerçek adı Robert Capa olarak doğmuştur', 'Magnum, ünlü fotoğrafçıdan sonra ona bu adı vermiştir', 'Capa takma adı yalnızca Kore Savaşı\'nda kullanılmıştır'], 'İki göçmen fotoğrafçı fotoğraflarını daha iyi satmak için 1936\'da hayali bir Amerikalı yarattı; sonra Friedmann bu adı sürekli kullandı.'),
  ('Hasselblad gibi yaprak perdeli deklanşöre sahip makinelerin flaş kullanımında üstünlüğü nedir?', 'Her enstantanede flaşla senkronize olabilmeleri', ['Daha ucuz olmaları', 'Yalnızca karanlıkta çalışmaları ve çok düşük ışıkta çalışmaları', 'Daha ağır olmaları'], 'Yaprak deklanşör objektif içindedir ve tam açıldığında flaşı ateşler; böylece yüksek hızlarda da flaş verilebilir.'),
  ('35 mm film için kullanılan "135" adı nereden gelir?', 'Kodak\'ın 1934\'te tanıttığı tek kartuş biçiminden', ['Filmin genişliğinden', 'Karenin uzunluğundan', 'Fiyatından'], '"135", metal kartuştaki 35 mm filmin standart adı olmuş; Kodak Retina ile yaygınlaşmıştır.'),
  ('Ansel Adams, anında fotoğraf alanında hangi şirkete uzun yıllar danışmanlık yapmıştır?', 'Polaroid', ['Kodak\'ın rakibi Agfa', 'Leica', 'Hasselblad'], 'Adams, Edwin Land\'in şirketine fotoğrafik danışmanlık yapmış, anında filmin sanatsal olanaklarını denemiştir.'),
  ('Polaroid\'in 20 × 24 inç makinesi hangi özelliğiyle bilinir?', 'Dev boyutlu anında baskı vermesi', ['Çok küçük boyutlu olması', 'Yalnızca videoya çekim yapması ve karanlıkta çalışması', 'Dijital olması'], 'Bu dev makine, Paolo Roversi ve Chuck Close gibi sanatçıların büyük boyutlu anında baskılarında kullanılmıştır.'),
  ('Fotoğrafın sanatsal değerinin tanınmasında "baskı sayısını sınırlama" (edisyon) uygulaması neyi hedefler?', 'Eserin kıtlığını ve koleksiyon değerini güvence altına almayı', ['Baskı kalitesini düşürmeyi', 'Negatifi yok etmeyi', 'Boyutu küçültmeyi'], 'Sınırlı edisyon, fotoğrafın çoğaltılabilir doğasına karşın biricik sanat nesnesi gibi piyasaya sürülmesini sağlar.'),
  ('Rolleiflex gibi bel hizası vizörlü çift objektifli makinelerin verdiği kare formatlı negatif hangi boyuttadır?', '6 × 6 cm orta format', ['35 mm tam kare', '4 × 5 inç', '110 film'], 'Rolleiflex gibi çift objektifli makineler 6 × 6 cm kare negatif verir; portre ve sokak fotoğrafçıları tarafından sevilmiştir.'),
];
